def native(v):
 if isinstance(v,np.generic): return v.item()
 if isinstance(v,np.ndarray): return v.tolist()
 if isinstance(v,dict): return {k:native(x) for k,x in v.items()}
 if isinstance(v,(tuple,list)): return [native(x) for x in v]
 return v
def dump(n,v): OUT.mkdir(parents=True,exist_ok=True); (OUT/n).write_text(json.dumps(native(v),indent=2,sort_keys=True)+'\n')
def save(n,**v): OUT.mkdir(parents=True,exist_ok=True); np.savez_compressed(OUT/n,**v)
def git(*a): return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
